import os, signal, subprocess, sys, time, urllib.request, urllib.error

def probe(url, data=None, method=None, headers=None):
    req = urllib.request.Request(url, data=data, method=method, headers=headers or {})
    try:
        with urllib.request.urlopen(req, timeout=5) as r:
            return r.status, r.read().decode()[:120]
    except urllib.error.HTTPError as e:
        return e.code, e.read().decode()[:120]

CASES = [
    ("todo.py",             5101, [("GET", "/todos", None), ("PUT", "/todos/todo1", b"task=direct")]),
    ("todo_simple.py",      5102, [("PUT", "/todo1", b"data=milk"), ("GET", "/todo1", None)]),
    ("xml_representation.py",5103,[("GET", "/me", None)]),
]

for name, port, reqs in CASES:
    env = dict(os.environ, FLASK_RUN_PORT=str(port))
    p = subprocess.Popen([sys.executable, "/workspace/examples/" + name],
                         env=env, stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
                         preexec_fn=os.setsid, cwd="/tmp/scratch")
    # examples hardcode app.run() -> port 5000; patch via a wrapper instead if needed
    time.sleep(3.0)
    alive = p.poll() is None
    print("=== %s: process alive after 3s: %s (rc=%s)" % (name, alive, p.poll()))
    if alive:
        for meth, path, body in reqs:
            hdrs = {"Content-Type": "application/x-www-form-urlencoded"} if body else {}
            try:
                print("    %-4s %-14s -> %s %r" % (meth, path, ) + () if False else ("    %-4s %-14s -> %s %r" % (meth, path, *probe("http://127.0.0.1:5000"+path, body, meth, hdrs))))
            except Exception as e:
                print("    %-4s %-14s -> ERR %r" % (meth, path, e))
    out = b""
    try:
        os.killpg(os.getpgid(p.pid), signal.SIGTERM)
    except Exception:
        pass
    time.sleep(0.5)
    try:
        out = p.stdout.read() or b""
    except Exception:
        pass
    print("    server log: %r" % out.decode(errors="replace")[:400])
PY
